package main
import("context";"database/sql";"encoding/json";"os";"time";"github.com/davidadel66/evie/internal/eviedb")
func main(){ var b [1]byte; _,_ = os.Stdin.Read(b[:]);ctx,cancel:=context.WithTimeout(context.Background(),20*time.Second);defer cancel();started:=time.Now();var db *sql.DB;var err error;if len(os.Args)>2 && os.Args[2]=="connect"{db,err=sql.Open("sqlite",os.Args[1]+"?_pragma=busy_timeout(5000)&_pragma=foreign_keys(1)&_pragma=journal_mode(WAL)");if err==nil{err=db.PingContext(ctx)}}else{db,err=eviedb.OpenDBAtContext(ctx,os.Args[1])};out:=map[string]any{"duration_ms":time.Since(started).Milliseconds(),"ok":err==nil};if err!=nil{out["error"]=err.Error()}else{var mode string;err=db.QueryRowContext(ctx,"PRAGMA journal_mode").Scan(&mode);out["journal_mode"]=mode;if err!=nil{out["error"]=err.Error();out["ok"]=false};_ = db.Close()};_ = json.NewEncoder(os.Stdout).Encode(out);if out["ok"]==false{os.Exit(1)}}
